select gc.shop_id as dealerShopId,gc.common_id,gc.common_name,gc.cat_name,gc.common_image, ifnull(gmgc.common_price,gb.goods_price) as common_price,gc.common_update_time, gb.common_stock as common_stock,gc.common_verify_time,gc.common_is_locked,gc.shop_name, gc.common_sell_time,gc.common_state,gc.common_cost_price,gc.common_salenum,gc.common_verify, gc.goods_id,gc.type,gc.common_add_time, gc.dealer_goods_flag,dc.sell_edit,dc.sell_edit_price, gc.common_stock as weighingGoodsStock,gc.supplier_source from ${database.prefix.goods}hou_goods_common gc left join ${database.prefix.goods}hou_goods_common gmgc on gc.common_parent_id=gmgc.common_id left join (select aa.common_id,aa.goods_price,aa.is_delete,aa.goods_is_shelves,sum(gs.goods_stock) AS common_stock from ${database.prefix.goods}hou_goods_base aa LEFT JOIN ${database.prefix.goods}hou_goods_stock gs on aa.goods_id = gs.goods_id where aa.is_delete = 0 and aa.goods_is_shelves=1 GROUP BY aa.common_id order by aa.goods_price ) as gb on gc.common_id = gb.common_id left join ${database.prefix.base}hou_base_dealer_putaway_record gr on gc.common_id = gr.dealer_common_id left join goods_delay_config dc on gr.supply_common_id = dc.common_id where gc.shop_status = 3 and gc.common_verify = 1 and gc.common_state = 1 and gb.is_delete = 0 and gb.goods_is_shelves=1 AND (gc.integral_goods <> 0 or gc.integral_goods is null)
and gc.shop_id = #{param.shopId}
and gc.plu LIKE CONCAT('%',#{param.plu},'%')
and gc.supply_shop_id = #{param.supplyShopId}
and gc.shop_id = #{param.dealerShopId}
and gc.shop_name LIKE CONCAT('%',#{param.dealerShopName},'%')
and gc.virtual_goods <> 3
and gc.virtual_goods = #{param.virtualGoods}
and gc.supplier_source = #{param.supplierSource}
and gc.common_name LIKE CONCAT('%',#{param.commonName },'%')
and gc.dealer_goods_flag = #{param.dealerGoodsFlag}
and gc.international_transport_template != 0
and gc.international_transport_template = 0
group by gc.common_id order by gc.common_update_time desc

