select gc.common_id,gb.goods_id,gc.common_name,gc.common_price,gc.common_market_price,gc.common_image, gc.virtual_goods,gc.period_of_validity,gc.past_due, gc.common_salenum,gc.common_promotion_tips,gc.common_evaluate, gc.common_collect, gc.shop_id,gc.shop_name, gc.common_add_time, gc.common_is_xian, gc.integral_goods, gb.need_integral, sg.shop_gate_id, sg.shop_gate_name, sg.longitude, sg.latitude, IF ( isnull( `gc`.`common_evaluate` ), 0, `gc`.`common_evaluate` ) AS `qty` FROM ${database.prefix.goods}hou_goods_common gc INNER JOIN (select goods_id,common_id,need_integral from ${database.prefix.goods}hou_goods_base where goods_is_shelves = 1 and is_delete <> 1 group by common_id ) gb on gb.common_id = gc.common_id LEFT JOIN ${database.prefix.supplier}hou_shop_base sb ON gc.shop_id = sb.supplier_shop_id left join ${database.prefix.business}hou_shop_level sl on sl.id = sb.shop_level_id LEFT JOIN goods_common_attribute_association caa on caa.common_id = gb.common_id LEFT JOIN ${database.prefix.business}hou_shop_gate_goods_base ggb on gc.common_id = ggb.common_id LEFT JOIN ${database.prefix.business}hou_shop_gate sg on sg.shop_gate_id = ggb.shop_gate_id WHERE gc.common_verify = 1 and gc.goods_type <> 2 and gc.virtual_goods <> 3
and ggb.shop_gate_id = #{param.shopGateId}
and gc.brand_id in
#{brandId}
and caa.attribute_content_id in
#{attributeContentId}
and sb.shop_type <> 2
and gc.integral_goods = #{param.integralGoods}
AND sb.shop_status = 3
AND gc.common_state = 1 and gc.common_is_screen=1
and gc.common_name LIKE CONCAT('%',#{param.commonName },'%')
and gc.shop_id = #{param.shopId,jdbcType=INTEGER}
and gc.goods_type <> 3
and gc.shop_self_support = #{param.shopSelfSupport}
and gc.cat_id = #{param.catId}
and gc.cat_id in
#{catId}
and gc.common_price >= #{param.minPrice}
and gc.common_price <= #{param.maxPrice}
GROUP BY gc.common_id order by sl.goods_list_first_show desc,sl.id desc
,gc.common_add_time desc
